/** The source text of `free/chart-export/csv-only.tsx`, as the Usage tab shows it. */
export default '/**\n * Stackra file contract:\n * Purpose: the "csv-only" demo of the native ChartExport: the numbers only: a CSV of the raw figures, ready for a spreadsheet.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371 (gap wave, owner approval 2026-10-31).\n */\nimport { BarChart, ChartExport, useCatalogueText } from "@stackra/ui/native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { CHART_EXPORT_DEMO_KEYS } from "#src/demos/free/chart-export/chart-export-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = CHART_EXPORT_DEMO_KEYS.demo_free.chart_export.csv_only;\n\n/** Six months of sales. */\nconst MONTHS = [\n  { month: "jan", sales: 42_000 },\n  { month: "feb", sales: 38_500 },\n  { month: "mar", sales: 51_200 },\n  { month: "apr", sales: 47_800 },\n  { month: "may", sales: 56_300 },\n  { month: "jun", sales: 61_900 },\n] as const;\n\n/** Chart export: csv only. */\nexport default function CsvOnly() {\n  const t = useCatalogueText(MESSAGES.en);\n  return (\n    <ChartExport\n      fileName="sales-riyadh"\n      formats={["csv"]}\n      data={{\n        head: [t(K.month), t(K.sales)],\n        rows: MONTHS.map((row) => [t(K[row.month]), row.sales]),\n      }}\n    >\n      <BarChart\n        label={t(K.label)}\n        data={MONTHS.map((row) => ({ name: t(K[row.month]), sales: row.sales }))}\n        series={[{ key: "sales", label: t(K.sales) }]}\n        xKey="name"\n      />\n    </ChartExport>\n  );\n}\n';
